import type { CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import type { PermsCapability, PermsTier } from "@/shared/lib/session/rolePermsRead";

const MONO = "var(--mono)";

// THE CAPABILITY IS HANDED IN — this component no longer knows what any role may do
// (`toolsview-shows-triage-permissions-for-fifteen-of-nineteen-roles`).
//
// It used to vendor a four-role ROLE_DEFAULTS table and return `ROLE_DEFAULTS[role] ??
// ROLE_DEFAULTS.triage`. MEASURED against `bsc session perms all`: fifteen of the gate's nineteen roles
// rendered a posture that was not theirs — including all four the table hardcoded — and the four that
// happened to be right (juror, operator, reviewer, tester) were coincidences of the fallback. The
// fallback was not even triage: the gate resolves triage as github WRITE / git none, the table said
// github read / git read. A designer, an operator or a librarian was shown a capability it does not
// have, and because the fallback returned a COMPLETE-LOOKING row, the wrong answer read as a deliberate
// one.
//
// It cannot read the gate itself, and that is a boundary rather than laziness: a kit component is
// compiled and mounted in a sandbox with no `bsc` bridge, which is why the table was vendored in the
// first place. So the capability arrives as a PROP, resolved once by the caller from
// `bsc session perms all` (see `rolePermsRead`), and this stays synchronous.
//
// THREE DISTINCT ANSWERS, AND NONE OF THEM IS ANOTHER ROLE'S ROW. The vocabulary is `rolePermsRead`'s,
// reused deliberately rather than reinvented — a second vocabulary for the same distinctions is how two
// readers end up disagreeing about what "nothing" meant:
//
//   * `cap` present                → render exactly what the gate resolved.
//   * `cap` null, `capRead: "ok"`  → the read RAN and carries no row for this role. Say so.
//   * `cap` null, `capRead` absent → the read has not answered yet. Say THAT, not "unreadable" —
//                                    reporting a failure during the in-flight window is its own lie.
//   * `cap` null, `"unreadable"`   → the read could not run at all (no bridge, no bundled binary).
//
// There is deliberately nothing left here for a `??` to fall through to. A DEFAULT THAT LOOKS LIKE DATA
// IS THE DEFECT, so an unresolved role renders a stated absence and no tiers whatsoever.
//
// `role` defaults to EMPTY, not to "worker". The old default meant an ad-hoc console with no role
// assigned rendered a worker's posture — the same fabrication one level up. Absent now takes the
// ungated panel, which is the honest answer and also what a props-less preview mount gets.

/** Whether the role→capability read could RUN. Absent means it has not answered yet — a third state,
 *  distinct from both a successful read with no row and a read that failed. */
export type ToolsCapRead = "ok" | "unreadable";

export interface ToolsViewProps {
  /** The session role this pane runs under. Empty/absent = an ungated interactive console. */
  role?: string;
  /** Compact chrome, for parity with the other pane views. Nothing here varies on it. */
  small?: boolean;
  /** What the gate resolved for `role`, or `null` when it resolved nothing. NEVER another role's row. */
  cap?: PermsCapability | null;
  /** Did the read RUN? Absent = still reading. */
  capRead?: ToolsCapRead;
}

/** Map an access tier to a themed color: write => green, read => amber, none => red. */
function tierColor(t: PermsTier) {
  return t === "write" ? "var(--state-run)" : t === "read" ? "var(--state-wait)" : "var(--state-stopped)";
}

const grpLabel: CSSProperties = {
  color: "var(--fg-dim)", fontSize: 9.5, letterSpacing: ".08em", fontFamily: MONO,
};

const shell: CSSProperties = {
  flex: 1, minHeight: 0, overflow: "auto", fontFamily: MONO, fontSize: 11.5, color: "var(--fg-muted)",
};

/** The six access axes the gate resolves. All six, not the three the vendored table carried: showing a
 *  subset is a smaller version of the same problem, since the axes it drops read as absent rather than
 *  as unshown. */
const AXES: ReadonlyArray<readonly ["github" | "git" | "code" | "net" | "ui" | "graph", string]> = [
  ["github", "issues / PRs / API mutations"],
  ["git", "commit / push / merge"],
  ["code", "edit files on disk"],
  ["net", "outbound network"],
  ["ui", "the component + kit stores"],
  ["graph", "the algorithms store"],
];

export function ToolsView({ role = "", small, cap, capRead }: ToolsViewProps) {
  void small;
  if (!role) {
    return (
      <Box pad={[12, 13]} style={{ ...shell, lineHeight: 1.7 }}>
        <Text as="div" style={grpLabel}>PERMISSIONS</Text>
        <Text as="div" tone="dim" style={{ marginTop: 8 }}>
          Interactive console — no least-privilege role applied. Launched fleet sessions
          (worker / director / triage / ...) show their capability posture here.
        </Text>
      </Box>
    );
  }

  if (!cap) {
    // The role is known, its capability is not. Say which of the three reasons applies and render NO
    // tiers — borrowing another role's row is precisely the defect this component was filed for.
    const state = capRead === "ok" ? "unknown-role" : capRead === "unreadable" ? "unreadable" : "pending";
    const why =
      state === "unknown-role" ? "The role gate resolved no capability for this role."
      : state === "unreadable" ? "The role gate could not be read here."
      : "Reading the role gate…";
    return (
      <Box pad={[12, 13]} style={{ ...shell, lineHeight: 1.7 }}>
        <Text as="div" style={{ ...grpLabel, marginBottom: 7 }}>ROLE · {role.toUpperCase()}</Text>
        <Text as="div" tone="dim" data-unresolved={state}>{why}</Text>
        <Text as="div" tone="dim" size={10.5} style={{ marginTop: 8 }}>
          No posture is shown, deliberately — another role's row would read as this one's.
        </Text>
      </Box>
    );
  }

  const globs = cap.writeGlobs.length ? cap.writeGlobs : null;

  return (
    <Box pad={[12, 13]} style={{ ...shell, lineHeight: 1.6 }}>
      <Text as="div" style={{ ...grpLabel, marginBottom: 7 }}>ROLE · {role.toUpperCase()}</Text>
      {AXES.map(([key, note]) => (
        <Row key={key} gap={9} style={{ padding: "4px 6px", borderRadius: 6 }}>
          <Text style={{ color: tierColor(cap[key]), width: 12 }}>●</Text>
          <Text style={{ color: "var(--fg)", width: 60 }}>{key}</Text>
          <Text tone="dim" size={10} style={{ flex: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{note}</Text>
          <Text size={10} data-axis={key} data-tier={cap[key]} style={{ color: tierColor(cap[key]) }}>{cap[key]}</Text>
        </Row>
      ))}

      <Text as="div" style={{ ...grpLabel, margin: "12px 0 6px" }}>WRITE PATHS</Text>
      {globs ? (
        <Row gap={5} wrap align="stretch">
          {globs.map((g) => (
            <Text key={g} tone="muted" size={10} data-glob={g} style={{ padding: "1px 6px", borderRadius: 5, background: "var(--bg-elev2)" }}>{g}</Text>
          ))}
        </Row>
      ) : (
        <Text as="div" tone="dim" size={10.5}>
          {cap.code === "none" ? "no code writes — read-only role" : "owned globs only (assigned at fleet launch)"}
        </Text>
      )}

      <Text as="div" style={{ ...grpLabel, margin: "12px 0 6px" }}>MCP SERVERS</Text>
      <Text as="div" tone="dim" size={10.5}>Attached per project at launch — see the project's MCP pane.</Text>
    </Box>
  );
}
